using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.EntityFrameworkCore;
using Microsoft.IdentityModel.Tokens;
using ProjectTimeline.BusinessLogic;
using ProjectTimeline.DataAccessLogic;
using ProjectTimeline.Database;

var builder = WebApplication.CreateBuilder(args);
var connection = builder.Configuration.GetConnectionString("ProjectTimeline") ?? "Host=localhost;Database=projecttimeline;Username=postgres";
var jwtKey = builder.Configuration["Authentication:SigningKey"] ?? "development-only-project-timeline-signing-key-change-me-32chars";
builder.Services.AddDbContext<ProjectTimelineDbContext>(o => o.UseNpgsql(connection));
builder.Services.AddScoped<TimelineService>(); builder.Services.AddScoped<ProjectService>();
builder.Services.AddSingleton<ArtifactStorage>();
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o => o.TokenValidationParameters = new TokenValidationParameters { ValidateIssuer = false, ValidateAudience = false, ValidateIssuerSigningKey = true, IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwtKey)), ValidateLifetime = true });
builder.Services.AddAuthorization(); builder.Services.AddCors(o => o.AddDefaultPolicy(p => p.AllowAnyOrigin().AllowAnyHeader().AllowAnyMethod()));
var app = builder.Build(); app.UseCors(); app.UseDefaultFiles(); app.UseStaticFiles(); app.UseAuthentication(); app.UseAuthorization();
using (var scope = app.Services.CreateScope()) { try { var db = scope.ServiceProvider.GetRequiredService<ProjectTimelineDbContext>(); var hash = Environment.GetEnvironmentVariable("PROJECT_TIMELINE_ADMIN_PASSWORD_HASH") ?? PasswordService.Hash(Environment.GetEnvironmentVariable("PROJECT_TIMELINE_ADMIN_PASSWORD") ?? "development-password-change-me"); await DatabaseSetup.MigrateAndSeedAsync(db, hash); } catch (Exception ex) { app.Logger.LogWarning("Database initialization is unavailable; API remains available for diagnostics: {Message}", ex.Message); } }

app.MapPost("/api/auth/login", async (LoginRequest request, ProjectTimelineDbContext db) => { var user = await db.Users.Include(x => x.Roles).SingleOrDefaultAsync(x => x.Email == request.Email.ToLower() && x.IsActive); if (user is null || !PasswordService.Verify(request.Password, user.PasswordHash)) return Results.Unauthorized(); var token = new JwtSecurityTokenHandler().WriteToken(new JwtSecurityToken(claims: [new Claim(ClaimTypes.NameIdentifier, user.Id.ToString()), new Claim(ClaimTypes.Email, user.Email)], expires: DateTime.UtcNow.AddHours(8), signingCredentials: new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwtKey)), SecurityAlgorithms.HmacSha256))); return Results.Ok(new { token, user = new UserDto(user.Id, user.Email, user.DisplayName, user.IsActive, user.Roles.Select(r => r.RoleName)) }); });
app.MapPost("/api/auth/recovery", (string email) => Results.Ok(new { message = "If the account exists, recovery instructions will be available through the configured local recovery channel." }));
app.MapGet("/api/me", async (ClaimsPrincipal principal, ProjectTimelineDbContext db) => { var id = Guid.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!); var u = await db.Users.Include(x => x.Roles).SingleOrDefaultAsync(x => x.Id == id); return u is null ? Results.NotFound() : Results.Ok(new UserDto(u.Id, u.Email, u.DisplayName, u.IsActive, u.Roles.Select(r => r.RoleName))); }).RequireAuthorization();
app.MapGet("/odata/projects", async (int? top, string? filter, string? orderby, ProjectTimelineDbContext db) => { var query = db.Projects.AsNoTracking().Select(p => new { p.Id, p.Code, p.Name, p.Description, p.OwnerId, p.CreatedAtUtc, p.UpdatedAtUtc }); if (!string.IsNullOrWhiteSpace(filter) && filter.Contains("code", StringComparison.OrdinalIgnoreCase)) { var value = filter.Split(' ', StringSplitOptions.RemoveEmptyEntries).LastOrDefault()?.Trim('\'', '"'); if (value is not null) query = query.Where(x => x.Code.Contains(value)); } if (string.Equals(orderby, "name", StringComparison.OrdinalIgnoreCase)) query = query.OrderBy(x => x.Name); return Results.Ok(await query.Take(Math.Clamp(top ?? 50, 1, 100)).ToListAsync()); }).RequireAuthorization();
app.MapGet("/api/projects", async (ProjectTimelineDbContext db) => Results.Ok(await db.Projects.AsNoTracking().Select(p => new { p.Id, p.Code, p.Name, p.Description, p.OwnerId, p.CreatedAtUtc, p.UpdatedAtUtc }).ToListAsync())).RequireAuthorization();
app.MapPost("/api/projects", async (CreateProjectRequest request, ClaimsPrincipal principal, ProjectService service, CancellationToken ct) => { var owner = Guid.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!); try { var p = await service.CreateAsync(owner, request.Code, request.Name, request.Description, ct); return Results.Created($"/api/projects/{p.Id}", new { p.Id, p.Code, p.Name, p.Description, p.OwnerId }); } catch (Exception ex) when (ex is ArgumentException or DbUpdateException) { return Results.BadRequest(new { error = ex.Message }); } }).RequireAuthorization();
app.MapPut("/api/me", async (UpdateProfileRequest request, ClaimsPrincipal principal, ProjectTimelineDbContext db) => { var id = Guid.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!); var user = await db.Users.FindAsync(id); if (user is null) return Results.NotFound(); user.DisplayName = request.DisplayName.Trim(); if (!string.IsNullOrWhiteSpace(request.Password)) user.PasswordHash = PasswordService.Hash(request.Password); await db.SaveChangesAsync(); return Results.Ok(new { user.Id, user.Email, user.DisplayName }); }).RequireAuthorization();
app.MapGet("/api/admin/users", async (ProjectTimelineDbContext db) => Results.Ok(await db.Users.Include(x => x.Roles).Select(x => new UserDto(x.Id, x.Email, x.DisplayName, x.IsActive, x.Roles.Select(r => r.RoleName))).ToListAsync())).RequireAuthorization();
app.MapPost("/api/projects/{projectId:guid}/participants", async (Guid projectId, AddParticipantRequest request, ClaimsPrincipal principal, ProjectTimelineDbContext db) => { var owner = Guid.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!); if (!await db.Projects.AnyAsync(x => x.Id == projectId && x.OwnerId == owner)) return Results.Forbid(); var user = await db.Users.SingleOrDefaultAsync(x => x.Email == request.Email.ToLower()); if (user is null) return Results.NotFound(new { error = "User not found." }); if (request.ProjectRoleName is not ("Creator" or "Reviewer" or "Contributor")) return Results.BadRequest(new { error = "Invalid project role." }); db.ProjectParticipants.Add(new ProjectParticipant { ProjectId = projectId, UserId = user.Id, ProjectRoleName = request.ProjectRoleName, IsInvited = true }); await db.SaveChangesAsync(); return Results.Ok(); }).RequireAuthorization();
app.MapPost("/api/projects/{projectId:guid}/timelines", async (Guid projectId, CreateTimelineRequest request, ClaimsPrincipal principal, ProjectTimelineDbContext db) => { var owner = Guid.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!); if (!await db.Projects.AnyAsync(x => x.Id == projectId && x.OwnerId == owner)) return Results.Forbid(); var t = new Timeline { ProjectId = projectId, Code = request.Code.Trim().ToUpperInvariant(), Name = request.Name.Trim() }; db.Timelines.Add(t); await db.SaveChangesAsync(); return Results.Created($"/api/timelines/{t.Id}", new { t.Id, t.Code, t.Name, t.ProjectId }); }).RequireAuthorization();
app.MapGet("/api/projects/{projectId:guid}/timelines", async (Guid projectId, ProjectTimelineDbContext db) => Results.Ok(await db.Timelines.AsNoTracking().Where(x => x.ProjectId == projectId).Select(x => new { x.Id, x.Code, x.Name, x.CreatedAtUtc, x.UpdatedAtUtc }).ToListAsync())).RequireAuthorization();
app.MapGet("/api/timelines/{timelineId:guid}/entries", async (Guid timelineId, ProjectTimelineDbContext db) => Results.Ok(await db.TimelineEntries.AsNoTracking().Where(x => x.TimelineId == timelineId).OrderBy(x => x.EntryNumber).Select(x => new { x.Id, x.EntryNumber, x.Title, x.Content, x.Status, x.AuthorId, x.CreatedAtUtc, x.UpdatedAtUtc }).ToListAsync())).RequireAuthorization();
app.MapPost("/api/timelines/{timelineId:guid}/entries", async (Guid timelineId, CreateEntryRequest request, ClaimsPrincipal principal, TimelineService service, CancellationToken ct) => { try { var e = await service.AddEntryAsync(timelineId, Guid.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!), request.Title, request.Content, ct); return Results.Created($"/api/entries/{e.Id}", new { e.Id, e.EntryNumber, e.Title, e.Content, e.Status }); } catch (Exception ex) when (ex is ArgumentException or KeyNotFoundException) { return Results.BadRequest(new { error = ex.Message }); } }).RequireAuthorization();
app.MapPost("/api/entries/{entryId:guid}/artifacts", async (Guid entryId, IFormFile file, ProjectTimelineDbContext db, ArtifactStorage storage, CancellationToken ct) => { var entry = await db.TimelineEntries.Include(x => x.Timeline).ThenInclude(x => x.Project).SingleOrDefaultAsync(x => x.Id == entryId, ct); if (entry is null) return Results.NotFound(); try { await storage.SaveAsync(entry.Timeline.Project.Code, entry.Timeline.Code, entry.EntryNumber, file.FileName, file.OpenReadStream(), ct); var artifact = new TimelineArtifact { EntryId = entryId, FileName = Path.GetFileName(file.FileName), RelativePath = $"{entry.Timeline.Project.Code}/{entry.Timeline.Code}/{entry.EntryNumber}/{Path.GetFileName(file.FileName)}", ContentType = file.ContentType, Length = file.Length }; db.TimelineArtifacts.Add(artifact); await db.SaveChangesAsync(ct); return Results.Ok(new { artifact.Id, artifact.FileName }); } catch (ArgumentException ex) { return Results.BadRequest(new { error = ex.Message }); } }).RequireAuthorization();
app.MapGet("/api/artifacts/{artifactId:guid}", async (Guid artifactId, ProjectTimelineDbContext db, ArtifactStorage storage, CancellationToken ct) => { var a = await db.TimelineArtifacts.Include(x => x.Entry).ThenInclude(x => x.Timeline).ThenInclude(x => x.Project).SingleOrDefaultAsync(x => x.Id == artifactId, ct); if (a is null) return Results.NotFound(); try { var path = storage.GetSafePath(a.Entry.Timeline.Project.Code, a.Entry.Timeline.Code, a.Entry.EntryNumber, a.FileName); if (!File.Exists(path)) return Results.NotFound(); return Results.File(path, a.ContentType, a.FileName); } catch (ArgumentException) { return Results.BadRequest(); } }).RequireAuthorization();
app.MapFallbackToFile("index.html");
app.Run();

public partial class Program { }
